# -*- coding: utf-8 -*-
"""编号对应、人工核对与一键改名页面。所有文件操作由本地后端执行。"""

PAGE = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>皿内菌落测量 · 编号与改名</title>
<style>
:root{--blue:#2864c3;--ink:#23334b;--muted:#68778d;--line:#e0e7f0;--paper:#fff;--back:#f4f7fb;--green:#167347;--amber:#986015}
*{box-sizing:border-box}body{margin:0;background:var(--back);color:var(--ink);font:14px/1.55 "Microsoft YaHei",system-ui,sans-serif}
button,input,select{font:inherit}button{cursor:pointer;border:1px solid #ccd7e6;border-radius:8px;padding:8px 14px;color:#344a67;background:#fff;transition:background .15s,box-shadow .15s}
button:hover:not(:disabled){background:#f0f5fd;border-color:#9db8df}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #95b8ee;outline-offset:2px}button:disabled{opacity:.48;cursor:wait}
button.primary{background:var(--blue);border-color:var(--blue);color:white}button.primary:hover:not(:disabled){background:#1e54a7}button.success{background:var(--green);border-color:var(--green);color:#fff}button.danger{border-color:#d09a8e;color:#a5402b}button.small{padding:5px 9px;font-size:12px}button.quiet{background:transparent;border-color:transparent;color:var(--blue)}
input[type=text],input[type=number],select{border:1px solid #cdd8e6;background:#fff;border-radius:7px;padding:7px 10px;color:var(--ink);min-width:0;max-width:100%}input[type=checkbox]{accent-color:var(--blue);width:16px;height:16px;vertical-align:middle;cursor:pointer}label{cursor:pointer}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}
header{position:sticky;top:0;z-index:10;background:#ffffffed;backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}.top{max-width:1460px;margin:auto;padding:13px 25px;display:flex;align-items:center;gap:13px}.logo{height:35px;width:35px;border-radius:11px;background:#e9f0ff;color:var(--blue);display:grid;place-items:center;font-size:22px;font-weight:700}.brand{font-weight:700;font-size:17px;letter-spacing:.3px}.version{font-size:12px;color:var(--muted);margin-left:6px;font-weight:400}.top a{margin-left:auto;font-size:13px}
main{max-width:1460px;margin:auto;padding:25px}.intro{display:flex;align-items:flex-start;gap:20px;margin-bottom:20px}.intro h1{margin:0 0 5px;font-size:26px;letter-spacing:.2px;font-weight:700}.intro p{color:var(--muted);margin:0;max-width:850px}.steps{display:flex;gap:8px;align-items:center;font-size:12px;color:#61738d;flex-wrap:wrap;margin-top:15px}.step{display:flex;align-items:center;gap:6px}.step i{font-style:normal;border-radius:50%;height:21px;width:21px;background:#e1eafb;color:var(--blue);display:grid;place-items:center;font-weight:700}.steps .arrow{color:#a2aec0;margin:0 4px}
.setup{display:grid;grid-template-columns:1.05fr 1fr;gap:15px;margin-bottom:20px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:13px;box-shadow:0 3px 12px #28436b05;padding:18px 20px}.panel h2{font-size:15px;margin:0 0 10px;display:flex;gap:8px;align-items:center}.panel h2 span{color:var(--muted);font-size:12px;font-weight:400}.folder-row{display:flex;gap:12px;align-items:center}.folder-row .path{overflow-wrap:anywhere;flex:1;font-size:12px;color:var(--muted);max-height:58px;overflow:auto}.mapping-top{display:flex;align-items:center;gap:12px}.map-empty{font-size:13px;color:var(--muted)}.map-chips{display:flex;gap:6px;flex-wrap:wrap;max-height:90px;overflow:auto;margin-top:9px}.chip{font-size:12px;background:#eff4fd;border:1px solid #dce6f7;border-radius:5px;padding:3px 8px;max-width:100%;overflow-wrap:anywhere}.chip b{color:var(--blue);margin-right:5px}.batch-info{color:var(--muted);font-size:12px;margin-top:9px}
.notice{display:flex;gap:10px;align-items:flex-start;background:#eef4ff;border:1px solid #dae7fb;border-radius:9px;padding:11px 14px;font-size:12px;color:#466180;margin-bottom:18px}.notice strong{color:#2e5286;white-space:nowrap}.message{display:none;border-radius:9px;padding:12px 15px;margin-bottom:14px;white-space:pre-wrap;overflow-wrap:anywhere}.message.show{display:block}.message.error{background:#fff0ec;border:1px solid #f0c6b9;color:#9a3a24}.message.info{background:#edf7f0;border:1px solid #c8e3d0;color:#1c623c}
.progress{display:none;background:white;border:1px solid var(--line);border-radius:10px;padding:14px 18px;margin-bottom:16px}.progress.show{display:block}.progress-head{display:flex;gap:16px;justify-content:space-between;font-size:13px}.progress-track{height:6px;background:#e9eff8;border-radius:10px;margin-top:9px;overflow:hidden}.progress-bar{height:100%;background:var(--blue);width:0;transition:width .3s}.progress-bar.indeterminate{width:35%;animation:slide 1.2s infinite alternate}@keyframes slide{to{transform:translateX(180%)}}
.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:13px}.toolbar h2{font-size:17px;margin:0}.count{font-size:12px;color:var(--muted)}.toolbar .spacer{flex:1}.search{width:195px}.filter{font-size:12px;display:flex;align-items:center;gap:5px;color:var(--muted)}.bulkbar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:15px}.bulkbar .hint{font-size:12px;color:var(--muted)}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:15px}.card{background:white;border:1px solid #dce4ef;border-radius:11px;overflow:hidden;box-shadow:0 2px 9px #213a6005}.card.confirmed{border-color:#b1d2bd}.image-button{display:block;border:0;border-radius:0;padding:0;width:100%;height:190px;background:#172130;position:relative;overflow:hidden}.image-button img{width:100%;height:100%;object-fit:contain;display:block}.image-button:hover:not(:disabled){background:#172130}.image-button .zoom{position:absolute;right:8px;bottom:7px;color:#fff;background:#111b2dbf;border-radius:4px;padding:2px 7px;font-size:11px;pointer-events:none}.badge{position:absolute;top:9px;left:9px;border-radius:5px;padding:3px 8px;background:#fff3dd;color:#835413;font-size:11px;box-shadow:0 1px 5px #0002}.confirmed .badge{color:#15613c;background:#e7f5eb}.card-body{padding:12px}.filename{font-size:12px;color:#536883;overflow-wrap:anywhere;line-height:1.5;min-height:36px;margin-bottom:9px}.filename small{display:block;color:#8794a6;font-size:10px}.assignment{display:grid;grid-template-columns:1fr 78px;gap:8px}.field label{display:block;color:var(--muted);font-size:11px;margin-bottom:3px}.field input,.field select{width:100%;font-size:12px;padding:7px 6px}.treatment{font-size:12px;font-weight:700;color:#28558e;margin-top:7px;min-height:19px;overflow-wrap:anywhere}.quick{display:flex;gap:4px;flex-wrap:wrap;margin-top:7px}.quick button{font-size:11px;padding:2px 7px;border-radius:4px;min-width:27px}.quick button.selected{border-color:#739bd4;background:#e8f0fd;color:#164e9d}.ocr-read{font-size:11px;line-height:1.5;color:var(--muted);min-height:18px;margin-top:8px;overflow-wrap:anywhere}.card-foot{border-top:1px solid #edf1f7;padding-top:9px;margin-top:9px;display:flex;align-items:center;justify-content:space-between;gap:5px}.confirm-label{display:flex;align-items:center;gap:5px;font-size:12px;color:#526581}.card.confirmed .confirm-label{color:#216640}.saving{font-size:10px;color:#946515;margin-left:4px}.empty{grid-column:1/-1;background:#fff;border:1px dashed #c9d7e8;border-radius:13px;text-align:center;padding:55px 20px;color:var(--muted)}.empty .emptyicon{font-size:34px;color:#8ea5c4;margin-bottom:8px}.empty strong{display:block;color:#405977;font-size:16px;font-weight:500;margin-bottom:6px}.empty p{margin:0 0 17px;font-size:13px}
.actions{position:sticky;bottom:12px;z-index:8;margin-top:24px;background:#ffffffed;backdrop-filter:blur(8px);box-shadow:0 5px 22px #1d3e711c;border:1px solid #d9e3ef;border-radius:12px;padding:15px 18px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}.action-info{margin-right:auto;min-width:190px}.action-info b{display:block;font-size:14px}.action-info small{font-size:11px;color:var(--muted)}.action-group{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.action-group label{font-size:12px;color:var(--muted)}.action-group input{width:65px;padding:6px}.action-group select{padding:6px;font-size:12px}.divider{height:29px;width:1px;background:var(--line);margin:0 3px}.success-panel{display:none;margin-top:20px;background:#f2faf4;border-color:#c5e0ce}.success-panel.show{display:block}.success-panel h2{color:var(--green)}.success-panel p{margin:4px 0;font-size:12px;color:#426952;overflow-wrap:anywhere}.success-panel .result-actions{margin-top:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.success-panel .result-actions span{font-size:12px;color:#5a7865}footer{font-size:11px;color:#8795a8;text-align:center;padding:23px 0 6px}
dialog{border:0;border-radius:15px;padding:0;color:var(--ink);width:min(760px,calc(100vw - 30px));max-height:92vh;box-shadow:0 20px 80px #0b1b3c4d;background:#fff}dialog::backdrop{background:#11213d85;backdrop-filter:blur(3px)}.dialog-head{padding:18px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;position:sticky;top:0;background:#fff;z-index:2}.dialog-head h2{font-size:18px;margin:0;flex:1}.dialog-head .close{font-size:22px;line-height:1;padding:3px 8px;border:0;color:#7e8b9f}.dialog-body{padding:20px 22px}.dialog-body>p{margin-top:0;color:var(--muted);font-size:13px}.dialog-foot{padding:14px 22px;border-top:1px solid var(--line);display:flex;gap:10px;align-items:center;justify-content:flex-end;background:#f9fbfe;position:sticky;bottom:0;z-index:2}.dialog-foot .footnote{font-size:11px;color:var(--muted);margin-right:auto}.metadata{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:19px}.metadata label{display:flex;flex-direction:column;gap:5px;font-size:12px;color:var(--muted)}.mapping-table{width:100%;border-collapse:collapse;font-size:13px}.mapping-table th{text-align:left;color:#6c7f99;font-size:11px;font-weight:400;padding:0 5px 6px}.mapping-table td{padding:4px 5px}.mapping-table input{width:100%}.mapping-table td:first-child{width:95px}.mapping-table td:last-child{width:45px}.mapping-table .remove{border:0;color:#9b6b60;background:#fff4f0}.mapping-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px}.mapping-tools .file-input{display:none}.mapping-tools button{font-size:12px}.helper{font-size:11px;color:#7c8da4;margin-top:13px}.dialog-error{display:none;color:#a13e25;background:#fff1eb;border-radius:6px;padding:9px 12px;font-size:12px;margin:0 0 12px;white-space:pre-wrap}.dialog-error.show{display:block}
#previewDialog{width:min(1050px,calc(100vw - 30px))}.preview-top{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:13px}.mode-label{font-size:12px;color:#536b89;display:flex;gap:5px;align-items:center}.mode-hint{font-size:12px;color:var(--muted);background:#f2f6fd;padding:10px 12px;border-radius:7px;margin-bottom:13px}.preview-warning{font-size:12px;color:#986015;background:#fff7e9;border:1px solid #f0dfbc;padding:10px 12px;border-radius:7px;margin-bottom:12px;white-space:pre-wrap}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px;max-height:42vh}.preview-table{width:100%;border-collapse:collapse;min-width:550px;font-size:12px}.preview-table th{background:#f5f8fd;color:#627794;text-align:left;position:sticky;top:0}.preview-table td,.preview-table th{padding:9px 12px;border-bottom:1px solid #e9eef5;overflow-wrap:anywhere}.preview-table tr:last-child td{border-bottom:0}.preview-table td:nth-child(2){color:#225ba3}.pendingtext{color:var(--muted);font-size:12px}
#imageDialog{width:min(1100px,calc(100vw - 25px));max-height:97vh}.image-title{font-size:12px;color:var(--muted);font-weight:400;overflow-wrap:anywhere;margin-top:3px}.image-stage{position:relative;width:100%;height:65vh;background:#111a28;overflow:hidden;touch-action:none;cursor:crosshair;user-select:none}.image-stage img{width:100%;height:100%;object-fit:contain;display:block;pointer-events:none}.roi-box{display:none;position:absolute;border:2px solid #ffcc47;background:#ffcc4720;pointer-events:none}.roi-box.show{display:block}.image-help{padding:11px 20px;font-size:12px;color:var(--muted);display:flex;gap:10px;align-items:center;flex-wrap:wrap}.image-help span{flex:1}.image-settings{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-right:auto}.image-settings label{font-size:12px;color:var(--muted)}.image-settings select{font-size:12px;max-width:230px}.image-settings input{width:75px;font-size:12px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:900px){.setup{grid-template-columns:1fr}.top{padding:11px 16px}.intro h1{font-size:23px}main{padding:19px 16px}.actions{bottom:6px;gap:10px}.action-info{width:100%}.divider{display:none}.action-group{flex:1}.action-group button{flex:1}.image-settings{width:100%}.image-stage{height:57vh}}@media(max-width:560px){.brand{font-size:14px}.version{display:block;margin:0}.top a{font-size:11px}.grid{grid-template-columns:1fr}.image-button{height:240px}.toolbar .spacer{display:none}.search{flex:1;width:160px}.toolbar{gap:8px}.toolbar h2{width:100%}.metadata{grid-template-columns:1fr}.panel{padding:15px}.dialog-body{padding:16px}.dialog-head,.dialog-foot{padding:13px 16px}.dialog-foot{flex-wrap:wrap}.dialog-foot .footnote{width:100%}.actions{position:static}.action-group{width:100%;flex-wrap:wrap}.image-stage{height:52vh}}
</style>
</head>
<body>
<header><div class="top"><div class="logo" aria-hidden="true">◉</div><div class="brand">皿内菌落测量<span class="version">v2.1 · 编号识别与一键改名</span></div><a href="/results">查看已有测量结果 →</a></div></header>
<main>
  <section class="intro"><div><h1>写编号，处理全名交给软件</h1><p>每批填写一次编号对应表。识别皿盖上的数字，核对后即可统一改名、继续测量。</p><div class="steps" aria-label="操作步骤"><span class="step"><i>1</i> 选择照片</span><span class="arrow">→</span><span class="step"><i>2</i> 填写对应表</span><span class="arrow">→</span><span class="step"><i>3</i> 识别与核对</span><span class="arrow">→</span><span class="step"><i>4</i> 一键改名 / 测量</span></div></div></section>
  <div id="mainMessage" class="message" role="status" aria-live="polite"></div>
  <section class="setup">
    <div class="panel"><h2>实验照片 <span id="fileCount">尚未选择</span></h2><div class="folder-row"><button id="pickFolder" class="primary">选择照片文件夹</button><div id="folderPath" class="path">支持 JPG、PNG、BMP、TIFF，可包含子文件夹。</div></div><div class="batch-info" id="batchInfo">每个文件夹单独保存对应表与核对进度。</div></div>
    <div class="panel"><h2>编号对应表 <span>支持 1、2、3，也支持 11 等多位编号</span></h2><div class="mapping-top"><button id="openMapping">填写 / 编辑对应表</button><span id="mapStatus" class="map-empty">先告诉软件每个编号对应哪个处理。</span></div><div id="mappingChips" class="map-chips"></div></div>
  </section>
  <div class="notice"><strong>拍照小提示</strong><span>编号写大、完整入镜，避开反光。<b>1-2</b> 表示“处理 1 · 重复 2”；只写 <b>1</b> 时可以分组，重复号保留为未知。数字识别结果需人工核对。</span></div>
  <div id="jobProgress" class="progress" role="status" aria-live="polite"><div class="progress-head"><b id="jobTitle">正在处理</b><span id="jobCount"></span></div><div class="progress-track"><div id="jobBar" class="progress-bar"></div></div></div>
  <section aria-labelledby="photosTitle"><div class="toolbar"><h2 id="photosTitle">核对照片编号</h2><span id="counts" class="count">共 0 张</span><div class="spacer"></div><input id="search" class="search" type="text" placeholder="搜索文件名、编号、处理" aria-label="搜索照片"><label class="filter"><input id="pendingOnly" type="checkbox">只看未确认</label></div><div class="bulkbar"><button id="ocrAll" class="primary">自动识别全部编号</button><button id="confirmVisible">确认当前有效编号</button><span id="ocrMessage" class="hint">识别建议不会自动标为已确认。</span></div><div id="photoGrid" class="grid"></div></section>
  <section id="lastResult" class="panel success-panel" aria-live="polite"><h2 id="resultTitle">改名完成</h2><p id="resultDirectory"></p><p id="resultManifest"></p><div class="result-actions"><button id="undoRename" class="small">撤销这次直接改名</button><span id="resultExplain">原图与编号对应关系已记录在清单中。</span></div></section>
  <section class="actions" aria-label="批量操作"><div class="action-info"><b id="readyCount">先选择照片文件夹</b><small>默认生成改名副本，原照片保留。</small></div><div class="action-group"><button id="previewRename" class="primary">预览 / 一键改名</button></div><div class="divider"></div><div class="action-group"><label for="dishMm">皿径</label><input id="dishMm" type="number" value="86" min="1" max="1000" step="0.1" aria-label="皿径毫米"><label for="plugMm">菌饼</label><select id="plugMm" aria-label="菌饼直径"><option value="6">6 mm</option><option value="8">8 mm</option></select><button id="measure" class="success">使用编号分组开始测量</button><button id="measureOriginal" title="适用于文件名已经包含处理名称的照片">按原文件名直接测量</button></div></section>
  <footer>编号对应表、识别建议与人工确认分开记录，便于追溯每张照片。</footer>
</main>

<dialog id="mappingDialog" aria-labelledby="mappingTitle"><div class="dialog-head"><h2 id="mappingTitle">填写编号对应表</h2><button class="close" data-close="mappingDialog" aria-label="关闭对应表">×</button></div><form id="mappingForm"><div class="dialog-body"><div id="mappingError" class="dialog-error" role="alert"></div><p>本批每个编号对应一个完整处理条件。若同一种药有不同浓度，请分别填写编号和名称。</p><div class="metadata"><label>实验 / 批次名称<input id="experimentId" type="text" placeholder="例如：层出镰刀菌药敏试验" maxlength="120"></label><label>菌株 / 类别（可选）<input id="strainName" type="text" placeholder="例如：层出镰刀菌" maxlength="120"></label></div><table class="mapping-table"><thead><tr><th>皿盖编号</th><th>对应处理全名（可包含浓度）</th><th><span class="sr-only">操作</span></th></tr></thead><tbody id="mappingRows"></tbody></table><div class="mapping-tools"><button type="button" id="addMapping">＋ 添加一行</button><button type="button" id="addFour">填入编号 1–4</button><button type="button" id="importMapping">导入对应表</button><button type="button" id="exportMapping">导出对应表</button><input type="file" id="mappingFile" class="file-input" accept=".json,application/json"></div><div class="helper">示例：1 → 吡噻菌胺，2 → 丙环唑，11 → CK。编号按完整数字匹配，11 不会拆成两个 1。修改已有对应关系后，需要重新确认受影响照片。</div></div><div class="dialog-foot"><span class="footnote">保存到当前实验文件夹，下次可继续使用。</span><button type="button" data-close="mappingDialog">取消</button><button type="submit" id="saveMapping" class="primary">保存对应表</button></div></form></dialog>

<dialog id="previewDialog" aria-labelledby="previewTitle"><div class="dialog-head"><h2 id="previewTitle">核对改名预览</h2><button class="close" data-close="previewDialog" aria-label="关闭改名预览">×</button></div><div class="dialog-body"><div id="previewError" class="dialog-error" role="alert"></div><div class="preview-top"><label class="mode-label"><input type="radio" name="renameMode" value="copy" checked>生成改名副本（推荐）</label><label class="mode-label"><input type="radio" name="renameMode" value="rename">直接修改原文件名</label><span id="previewCount" class="count"></span></div><div id="modeHint" class="mode-hint">改名后的照片放入新的输出文件夹，原照片保留。</div><div id="previewWarnings" class="preview-warning" hidden></div><div class="table-wrap"><table class="preview-table"><thead><tr><th>原文件</th><th>改名后</th><th>处理</th><th>重复号</th></tr></thead><tbody id="previewRows"></tbody></table></div></div><div class="dialog-foot"><span class="footnote">仅使用已确认的编号；缺失或冲突时先返回修改。</span><button data-close="previewDialog">返回核对</button><button id="applyRename" class="primary">一键改名（生成副本）</button></div></dialog>

<dialog id="imageDialog" aria-labelledby="imageTitle"><div class="dialog-head"><div style="flex:1;min-width:0"><h2>查看照片与编号</h2><div id="imageTitle" class="image-title"></div></div><button class="close" data-close="imageDialog" aria-label="关闭照片">×</button></div><div id="imageStage" class="image-stage"><img id="fullImage" alt="实验照片原图" draggable="false"><div id="roiBox" class="roi-box"></div></div><div class="image-help"><span id="roiHelp">可用鼠标框选皿盖上的编号，再识别选区，减少其它文字干扰。</span><button id="clearRoi" class="small">清除选框</button><button id="ocrImage" class="small primary">识别本张编号</button></div><div id="imageError" class="dialog-error" style="margin:0 20px 10px" role="alert"></div><div class="dialog-foot"><div class="image-settings"><label for="imageCode">编号</label><select id="imageCode"></select><label for="imageReplicate">重复</label><input id="imageReplicate" type="text" inputmode="numeric" placeholder="未知"><label><input id="imageConfirmed" type="checkbox">已核对</label></div><button data-close="imageDialog">关闭</button><button id="saveImage" class="primary">保存本张</button></div></dialog>

<script>
(function(){
'use strict';
var state={folder:'',images:[],mapping:[],experiment_id:'',strain:'',ocr_available:false,ocr_message:''};
var busy=false, pendingWrites=0, writeQueue=Promise.resolve(), search='', onlyPending=false;
var preview=null, previewMode='copy', lastTransaction=null, viewer=null, roi=null, drag=null;
var viewerDirty=false, viewerDrafts={};
var jobTimer=null, jobPurpose='';
var $=function(id){return document.getElementById(id)};
function el(tag,cls,text){var n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function showMessage(text,kind){$('mainMessage').textContent=text||'';$('mainMessage').className='message'+(text?' show '+(kind||'error'):'')}
function dialogError(id,text){$(id).textContent=text||'';$(id).classList.toggle('show',!!text)}
function failText(err){return err&&err.message?err.message:String(err)}
async function api(path,payload){var opts=payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)};var r=await fetch(path,opts),j;try{j=await r.json()}catch(e){throw new Error('本地服务返回异常，请确认程序仍在运行。')}if(!r.ok||j.ok===false)throw new Error(j.error||j.message||('操作失败（'+r.status+'）'));return j}
function mappings(){return Array.isArray(state.mapping)?state.mapping:[]}
function treatment(code){var m=mappings().find(function(x){return String(x.code)===String(code)});return m?m.treatment:''}
function imageById(id){return state.images.find(function(x){return String(x.id)===String(id)})}
function validImage(im){return !!im.code&&!!treatment(im.code)}
function readyImage(im){return validImage(im)&&!!im.confirmed}
function visibleImages(){return state.images.filter(function(im){var s=[im.name,im.relative_path,im.code,treatment(im.code)].join(' ').toLowerCase();return (!search||s.indexOf(search)>=0)&&(!onlyPending||!im.confirmed)})}
function updateButtons(){
  var has=!!state.folder,imgs=state.images.length>0,map=mappings().length>0,ready=imgs&&state.images.every(readyImage);
  $('pickFolder').disabled=busy;
  $('openMapping').disabled=busy||!has;
  $('ocrAll').disabled=busy||!imgs||!map||state.ocr_available===false;
  $('confirmVisible').disabled=busy||!imgs||!map;
  $('previewRename').disabled=busy||pendingWrites>0||!ready;
  $('measure').disabled=busy||pendingWrites>0||!ready;
  $('measureOriginal').disabled=busy||pendingWrites>0||!imgs;
  $('saveMapping').disabled=busy;
  $('applyRename').disabled=busy||!preview||!preview.token;
  $('saveImage').disabled=busy;
  $('ocrImage').disabled=busy||!viewer||viewerDirty||state.ocr_available===false||!map;
  document.querySelectorAll('.card select,.card input,.card button').forEach(function(n){n.disabled=busy||n.dataset.unavailable==='1'});
  document.querySelectorAll('#mappingForm input,#mappingForm button:not([data-close]),input[name=renameMode],#imageCode,#imageReplicate,#imageConfirmed,#dishMm,#plugMm').forEach(function(n){n.disabled=busy});
}
function updateCounts(){
  var n=state.images.length,c=state.images.filter(readyImage).length;
  $('fileCount').textContent=n?n+' 张照片':'尚未选择';
  $('counts').textContent='共 '+n+' 张 · 已确认 '+c+' 张 · 待核对 '+(n-c)+' 张';
  $('readyCount').textContent=!n?'先选择照片文件夹':c===n?'全部 '+n+' 张已确认，可以改名或测量':'已确认 '+c+' / '+n+' 张，请继续核对';
  $('folderPath').textContent=state.folder||'支持 JPG、PNG、BMP、TIFF，可包含子文件夹。';
  $('folderPath').title=state.folder||'';
  $('mapStatus').textContent=mappings().length?'已设置 '+mappings().length+' 个处理':'先告诉软件每个编号对应哪个处理。';
  $('batchInfo').textContent=[state.experiment_id?'批次：'+state.experiment_id:'',state.strain?'菌株：'+state.strain:''].filter(Boolean).join('　')||'每个文件夹单独保存对应表与核对进度。';
  $('ocrMessage').textContent=state.ocr_message||(state.ocr_available===false?'数字识别组件不可用，可以直接点选编号完成改名。':'数字识别为实验功能，识别建议不会自动标为已确认。');
  updateButtons();
}
function renderMappingChips(){var box=$('mappingChips');box.replaceChildren();mappings().forEach(function(m){var n=el('span','chip'),b=el('b','',m.code);n.appendChild(b);n.appendChild(document.createTextNode('→ '+m.treatment));box.appendChild(n)})}
function fillCodeSelect(sel,code){sel.replaceChildren();var empty=el('option','','请选择编号');empty.value='';sel.appendChild(empty);mappings().forEach(function(m){var op=el('option','',String(m.code)+' · '+m.treatment);op.value=String(m.code);sel.appendChild(op)});if(code&&!treatment(code)){var unknown=el('option','',String(code)+' · 未设置处理');unknown.value=String(code);sel.appendChild(unknown)}sel.value=String(code||'')}
function refreshCardStatus(im,card){card.classList.toggle('confirmed',readyImage(im));card.querySelector('.badge').textContent=readyImage(im)?'已人工确认':'待核对';card.querySelector('.treatment').textContent=treatment(im.code)||'尚未选择处理';card.querySelector('.confirmed-input').checked=!!im.confirmed;card.querySelector('.code-select').value=String(im.code||'');card.querySelectorAll('.quick button').forEach(function(b){b.classList.toggle('selected',String(im.code)===b.dataset.code)});updateCounts()}
function queueAssignment(im,card){
  var payload={id:im.id,code:String(im.code||''),replicate:String(im.replicate||'').trim(),confirmed:!!im.confirmed};
  pendingWrites++;updateButtons();if(card)card.querySelector('.saving').textContent='保存中…';
  var current=writeQueue.then(function(){return api('/naming/assign',payload)});
  writeQueue=current.catch(function(){});
  current.then(function(){if(card)card.querySelector('.saving').textContent='已保存'}).catch(function(err){
    showMessage('该张照片保存失败：'+failText(err));
    im.confirmed=false;if(card)refreshCardStatus(im,card);
  }).finally(function(){pendingWrites--;if(card)setTimeout(function(){var n=card.querySelector('.saving');if(n)n.textContent=''},1400);updateButtons()});
  return current;
}
function cardFor(im){
  var card=el('article','card'+(readyImage(im)?' confirmed':''));card.dataset.id=im.id;
  var pic=el('button','image-button');pic.type='button';pic.setAttribute('aria-label','放大查看 '+im.name);
  var image=el('img');image.alt=im.name;image.loading='lazy';image.src=im.thumb?(String(im.thumb).startsWith('data:')?im.thumb:'data:image/jpeg;base64,'+im.thumb):'/naming/image?id='+encodeURIComponent(im.id);pic.appendChild(image);pic.appendChild(el('span','badge',readyImage(im)?'已人工确认':'待核对'));pic.appendChild(el('span','zoom','放大 / 框选编号'));pic.addEventListener('click',function(){openImage(im.id)});card.appendChild(pic);
  var body=el('div','card-body'),nm=el('div','filename',im.name);nm.title=im.relative_path||im.name;if(im.relative_path&&im.relative_path!==im.name)nm.appendChild(el('small','',im.relative_path));body.appendChild(nm);
  var assignment=el('div','assignment'),cf=el('div','field'),rf=el('div','field');var codeId='code_'+im.id,repId='rep_'+im.id;
  var cl=el('label','','处理编号');cl.htmlFor=codeId;var select=el('select','code-select');select.id=codeId;fillCodeSelect(select,im.code);cf.append(cl,select);
  var rl=el('label','','重复号');rl.htmlFor=repId;var rep=el('input','replicate-input');rep.id=repId;rep.type='text';rep.inputMode='numeric';rep.placeholder='未知';rep.value=String(im.replicate||'');rep.title='只填写皿盖上真实的重复号；不填则保留未知';rf.append(rl,rep);assignment.append(cf,rf);body.appendChild(assignment);
  body.appendChild(el('div','treatment',treatment(im.code)||'尚未选择处理'));
  var quick=el('div','quick');mappings().slice(0,10).forEach(function(m){var q=el('button','small'+(String(im.code)===String(m.code)?' selected':''),String(m.code));q.type='button';q.dataset.code=String(m.code);q.title=m.treatment;q.addEventListener('click',function(){im.code=String(m.code);im.confirmed=false;refreshCardStatus(im,card);queueAssignment(im,card)});quick.appendChild(q)});body.appendChild(quick);
  var suggestion=im.ocr_text?'识别文字：'+String(im.ocr_text):'可先自动识别，也可直接点选编号。';if(im.ocr_score!==null&&im.ocr_score!==undefined&&Number.isFinite(Number(im.ocr_score)))suggestion+=' · 得分 '+Number(im.ocr_score).toFixed(2)+'（需核对）';body.appendChild(el('div','ocr-read',suggestion));
  var foot=el('div','card-foot'),label=el('label','confirm-label'),check=el('input','confirmed-input');check.type='checkbox';check.checked=!!im.confirmed;label.append(check,document.createTextNode('编号已核对'),el('span','saving'));var ocr=el('button','small','识别本张');ocr.type='button';if(state.ocr_available===false)ocr.dataset.unavailable='1';ocr.addEventListener('click',function(){startOcr([im.id])});foot.append(label,ocr);body.appendChild(foot);card.appendChild(body);
  select.addEventListener('change',function(){im.code=select.value;im.confirmed=false;refreshCardStatus(im,card);queueAssignment(im,card)});
  rep.addEventListener('change',function(){im.replicate=rep.value.trim();im.confirmed=false;refreshCardStatus(im,card);queueAssignment(im,card)});
  check.addEventListener('change',function(){if(check.checked&&!validImage(im)){check.checked=false;showMessage('请先为这张照片选择对应表中有效的编号。');select.focus();return}im.confirmed=check.checked;refreshCardStatus(im,card);queueAssignment(im,card)});
  return card;
}
function renderGrid(){var grid=$('photoGrid');grid.replaceChildren();var list=visibleImages();if(!list.length){var empty=el('div','empty');empty.appendChild(el('div','emptyicon','▧'));empty.appendChild(el('strong','',!state.images.length?'先选择一批实验照片':'没有符合条件的照片'));empty.appendChild(el('p','',!state.images.length?'皿盖写编号，软件记录处理全名，核对后统一改名。':'可以调整搜索词，或取消“只看未确认”。'));if(!state.images.length){var pick=el('button','primary','选择照片文件夹');pick.addEventListener('click',pickFolder);empty.appendChild(pick)}grid.appendChild(empty)}else{var frag=document.createDocumentFragment();list.forEach(function(im){frag.appendChild(cardFor(im))});grid.appendChild(frag)}updateCounts()}
function displayResult(j,mode){lastTransaction=mode==='rename'&&j.can_undo!==false?j.transaction_id:null;$('lastResult').classList.add('show');$('resultTitle').textContent=(j.count||0)+' 张照片'+(mode==='copy'?'已生成改名副本':'已完成直接改名');$('resultDirectory').textContent='输出位置：'+(j.output_dir||state.folder);$('resultManifest').textContent='测量清单：'+(j.manifest_path||'');$('undoRename').hidden=!lastTransaction;$('resultExplain').textContent=mode==='copy'?'原照片保留；改名副本与对应清单已保存。':'已记录本次原文件名与新文件名，可以撤销。'}
async function loadState(){var s=await api('/naming/state');if(s.state)s=s.state;state=Object.assign({folder:'',images:[],mapping:[],experiment_id:'',strain:'',ocr_available:false,ocr_message:''},s);if(!Array.isArray(state.images))state.images=[];if(!Array.isArray(state.mapping))state.mapping=[];renderMappingChips();renderGrid();if(state.last_result&&state.last_result.mode==='rename'&&state.last_result.can_undo)displayResult(state.last_result,'rename');return state}
function setBusy(value){busy=value;updateButtons()}
async function pickFolder(){if(busy)return;showMessage('');setBusy(true);try{await writeQueue;var result=await api('/naming/pick',{});if(result.cancelled)return;lastTransaction=null;$('lastResult').classList.remove('show');await loadState();if(state.folder&&!mappings().length)openMapping()}catch(err){showMessage(failText(err))}finally{setBusy(false)}}
function openDialog(id){var d=$(id);if(!d.open)d.showModal()}
function closeDialog(id){$(id).close()}
document.querySelectorAll('[data-close]').forEach(function(b){b.addEventListener('click',function(){closeDialog(b.dataset.close)})});
$('imageDialog').addEventListener('close',function(){if(viewer&&viewerDirty)viewerDrafts[viewer]={code:$('imageCode').value,replicate:$('imageReplicate').value,confirmed:$('imageConfirmed').checked};viewer=null;roi=null;drag=null;viewerDirty=false});
function appendMapping(code,name){var tr=el('tr'),td1=el('td'),td2=el('td'),td3=el('td');var c=el('input');c.type='text';c.inputMode='numeric';c.placeholder='例如 11';c.value=code===undefined?'':String(code);c.setAttribute('aria-label','皿盖编号');var n=el('input');n.type='text';n.placeholder='例如：吡噻菌胺 100 mg/L';n.value=name||'';n.setAttribute('aria-label','对应处理全名');var remove=el('button','small remove','×');remove.type='button';remove.title='删除这一行';remove.setAttribute('aria-label','删除对应关系');remove.addEventListener('click',function(){tr.remove()});td1.appendChild(c);td2.appendChild(n);td3.appendChild(remove);tr.append(td1,td2,td3);$('mappingRows').appendChild(tr);return c}
function readMappingDraft(){var out=[];Array.from($('mappingRows').rows).forEach(function(tr){var ins=tr.querySelectorAll('input'),code=ins[0].value.trim(),name=ins[1].value.trim();if(!code&&!name)return;if(!/^\d+$/.test(code))throw new Error('编号请使用完整数字，例如 1、2、11；重复号在照片下方单独填写。');if(!name)throw new Error('编号 '+code+' 还没有填写处理名称。');if(out.some(function(m){return m.code===code}))throw new Error('编号 '+code+' 重复，请为每个编号只保留一行。');out.push({code:code,treatment:name})});if(!out.length)throw new Error('请至少填写一组编号和处理名称。');return out}
function openMapping(){if(!state.folder){showMessage('请先选择照片文件夹。');return}dialogError('mappingError','');$('experimentId').value=state.experiment_id||'';$('strainName').value=state.strain||'';$('mappingRows').replaceChildren();if(mappings().length)mappings().forEach(function(m){appendMapping(m.code,m.treatment)});else appendMapping('1','');openDialog('mappingDialog')}
$('addMapping').addEventListener('click',function(){var current=Array.from($('mappingRows').querySelectorAll('tr')).map(function(tr){return tr.querySelector('input').value.trim()});var next=1;while(current.includes(String(next)))next++;appendMapping(String(next),'').focus()});
$('addFour').addEventListener('click',function(){var existing=Array.from($('mappingRows').querySelectorAll('tr')).map(function(tr){return tr.querySelector('input').value.trim()});['1','2','3','4'].forEach(function(code){if(!existing.includes(code))appendMapping(code,'')})});
$('mappingForm').addEventListener('submit',async function(e){e.preventDefault();if(busy)return;dialogError('mappingError','');try{var mapping=readMappingDraft();setBusy(true);await writeQueue;await api('/naming/configure',{mapping:mapping,experiment_id:$('experimentId').value.trim(),strain:$('strainName').value.trim()});await loadState();closeDialog('mappingDialog');showMessage('对应表已保存。识别照片编号后，请核对并勾选“编号已核对”。','info')}catch(err){dialogError('mappingError',failText(err))}finally{setBusy(false)}});
$('importMapping').addEventListener('click',function(){$('mappingFile').click()});
$('mappingFile').addEventListener('change',async function(){var file=this.files[0];if(!file)return;try{var j=JSON.parse(await file.text()),rows=Array.isArray(j)?j:j.mapping;if(!Array.isArray(rows)||!rows.length)throw new Error('未找到 mapping 对应表。');rows.forEach(function(m){if(m.code===undefined||typeof m.treatment!=='string')throw new Error('每行需要 code（编号）和 treatment（处理名称）。')});$('mappingRows').replaceChildren();rows.forEach(function(m){appendMapping(String(m.code),m.treatment)});if(j.experiment_id!==undefined)$('experimentId').value=j.experiment_id;if(j.strain!==undefined)$('strainName').value=j.strain;dialogError('mappingError','')}catch(err){dialogError('mappingError','导入失败：'+failText(err))}finally{this.value=''}});
$('exportMapping').addEventListener('click',function(){try{var j={mapping:readMappingDraft(),experiment_id:$('experimentId').value.trim(),strain:$('strainName').value.trim()};var url=URL.createObjectURL(new Blob([JSON.stringify(j,null,2)],{type:'application/json;charset=utf-8'})),a=el('a');a.href=url;a.download='编号对应表.json';a.click();setTimeout(function(){URL.revokeObjectURL(url)},1000);dialogError('mappingError','')}catch(err){dialogError('mappingError',failText(err))}});
function showProgress(title,done,total){$('jobProgress').classList.add('show');$('jobTitle').textContent=title;$('jobCount').textContent=total?done+' / '+total:'';var bar=$('jobBar');bar.classList.toggle('indeterminate',!total);bar.style.width=total?Math.max(0,Math.min(100,done/total*100))+'%':''}
function endProgress(){$('jobProgress').classList.remove('show');$('jobBar').classList.remove('indeterminate')}
async function pollJob(){
  try{var j=await api('/naming/job');if(j.job)j=j.job;showProgress(jobPurpose==='measure'?'正在测量，请保持程序运行':'正在识别编号，完成后请人工核对',Number(j.done||0),Number(j.total||0));if(j.running){jobTimer=setTimeout(pollJob,700);return}if(j.error)throw new Error(j.error);endProgress();setBusy(false);if(jobPurpose==='measure'){window.location.href='/results';return}await loadState();if(viewer){var current=imageById(viewer);if(current)fillViewer(current)}showMessage('识别完成。请核对编号和重复号，再勾选确认；无法读取的照片可直接点选编号。','info')}
  catch(err){endProgress();setBusy(false);showMessage(failText(err));if(viewer)dialogError('imageError',failText(err));try{await loadState()}catch(ignore){}}
}
async function startOcr(ids,rect){if(busy)return;if(!mappings().length){showMessage('请先填写编号对应表。');return}if(viewer&&viewerDirty){dialogError('imageError','请先保存本张的修改，再进行识别。');return}showMessage('');dialogError('imageError','');setBusy(true);try{await writeQueue;var payload={};if(ids)payload.ids=ids;if(rect)payload.roi=rect;jobPurpose='ocr';await api('/naming/ocr',payload);showProgress('正在识别编号，完成后请人工核对',0,ids?ids.length:state.images.length);jobTimer=setTimeout(pollJob,350)}catch(err){endProgress();setBusy(false);showMessage(failText(err));if(viewer)dialogError('imageError',failText(err))}}
async function confirmVisible(){if(busy)return;var list=visibleImages().filter(function(im){return validImage(im)&&!im.confirmed});if(!list.length){showMessage('当前显示的照片没有可确认的有效编号。','info');return}setBusy(true);showMessage('');try{await writeQueue;for(var i=0;i<list.length;i++){var im=list[i];showProgress('保存人工确认',i,list.length);await api('/naming/assign',{id:im.id,code:im.code,replicate:String(im.replicate||'').trim(),confirmed:true});im.confirmed=true}await loadState();showMessage('已确认 '+list.length+' 张照片的编号。','info')}catch(err){showMessage(failText(err));await loadState()}finally{endProgress();setBusy(false)}}
function renderPreview(j){$('previewRows').replaceChildren();var rows=j.rows||[];rows.forEach(function(row){var tr=el('tr');tr.appendChild(el('td','',row.source||''));tr.appendChild(el('td','',row.target||''));tr.appendChild(el('td','',row.treatment||''));tr.appendChild(el('td','',row.replicate||'未知'));$('previewRows').appendChild(tr)});$('previewCount').textContent=rows.length+' 张照片';var warnings=Array.isArray(j.warnings)?j.warnings.join('\n'):String(j.warnings||'');$('previewWarnings').textContent=warnings;$('previewWarnings').hidden=!warnings;$('modeHint').textContent=previewMode==='copy'?'改名后的照片放入新的输出文件夹，原照片保留。':'将直接修改当前照片的文件名。软件会记录原名，并提供本次改名的撤销入口。';$('applyRename').textContent=previewMode==='copy'?'一键改名（生成副本）':'一键直接改名';$('applyRename').classList.toggle('danger',previewMode==='rename');updateButtons()}
async function loadPreview(){preview=null;dialogError('previewError','');$('previewCount').textContent='正在生成预览…';$('previewRows').replaceChildren();updateButtons();try{await writeQueue;var j=await api('/naming/preview',{mode:previewMode});preview=j;renderPreview(j)}catch(err){dialogError('previewError',failText(err));$('previewCount').textContent='预览未完成';updateButtons()}}
async function openPreview(){if(busy)return;previewMode='copy';document.querySelector('input[name=renameMode][value=copy]').checked=true;openDialog('previewDialog');setBusy(true);try{await loadPreview()}finally{setBusy(false)}}
document.querySelectorAll('input[name=renameMode]').forEach(function(input){input.addEventListener('change',async function(){if(!input.checked)return;previewMode=input.value;setBusy(true);try{await loadPreview()}finally{setBusy(false)}})});
$('applyRename').addEventListener('click',async function(){if(busy||!preview)return;dialogError('previewError','');setBusy(true);try{var j=await api('/naming/apply',{token:preview.token,mode:previewMode,dish_mm:Number($('dishMm').value),plug_mm:Number($('plugMm').value)});closeDialog('previewDialog');displayResult(j,previewMode);await loadState();showMessage('改名完成，接下来可以继续测量。','info')}catch(err){preview=null;dialogError('previewError',failText(err)+'\n请返回核对，再重新生成预览。')}finally{setBusy(false)}});
$('undoRename').addEventListener('click',async function(){if(busy||!lastTransaction)return;setBusy(true);try{await api('/naming/undo',{transaction_id:lastTransaction});lastTransaction=null;$('undoRename').hidden=true;$('resultTitle').textContent='已撤销本次直接改名';$('resultExplain').textContent='照片已恢复原文件名；操作记录保留。';await loadState();showMessage('本次直接改名已撤销，原文件名已恢复。','info')}catch(err){showMessage(failText(err))}finally{setBusy(false)}});
async function startMeasurement(useOriginalNames){if(busy)return;var dish=Number($('dishMm').value),plug=Number($('plugMm').value);if(!Number.isFinite(dish)||dish<=plug){showMessage('皿径需要大于菌饼直径，请检查参数。');$('dishMm').focus();return}setBusy(true);showMessage('');try{await writeQueue;jobPurpose='measure';await api('/naming/measure',{dish_mm:dish,plug_mm:plug,use_original_names:!!useOriginalNames});showProgress('正在测量，请保持程序运行',0,state.images.length);jobTimer=setTimeout(pollJob,350)}catch(err){endProgress();setBusy(false);showMessage(failText(err))}}
$('measure').addEventListener('click',function(){startMeasurement(false)});$('measureOriginal').addEventListener('click',function(){startMeasurement(true)});
function imageBounds(){var stage=$('imageStage').getBoundingClientRect(),img=$('fullImage'),nw=img.naturalWidth,nh=img.naturalHeight;if(!nw||!nh)return null;var scale=Math.min(stage.width/nw,stage.height/nh),w=nw*scale,h=nh*scale;return {left:stage.left+(stage.width-w)/2,top:stage.top+(stage.height-h)/2,width:w,height:h,stage:stage}}
function normalizedPoint(ev,clamp){var b=imageBounds();if(!b)return null;var x=(ev.clientX-b.left)/b.width,y=(ev.clientY-b.top)/b.height;if(!clamp&&(x<0||y<0||x>1||y>1))return null;return [Math.max(0,Math.min(1,x)),Math.max(0,Math.min(1,y))]}
function paintRoi(){var box=$('roiBox'),b=imageBounds();box.classList.toggle('show',!!roi&&!!b);if(!roi||!b)return;box.style.left=(b.left-b.stage.left+roi[0]*b.width)+'px';box.style.top=(b.top-b.stage.top+roi[1]*b.height)+'px';box.style.width=(roi[2]*b.width)+'px';box.style.height=(roi[3]*b.height)+'px';$('roiHelp').textContent='已框选编号区域。点“识别选区”，结果仍需核对。';$('ocrImage').textContent='识别选区'}
function clearRoi(){roi=null;drag=null;$('roiBox').classList.remove('show');$('roiHelp').textContent='可用鼠标框选皿盖上的编号，再识别选区，减少其它文字干扰。';$('ocrImage').textContent='识别本张编号'}
function fillViewer(im){fillCodeSelect($('imageCode'),im.code);$('imageReplicate').value=String(im.replicate||'');$('imageConfirmed').checked=!!im.confirmed;viewerDirty=false}
function openImage(id){var im=imageById(id);if(!im)return;viewer=id;clearRoi();dialogError('imageError','');$('imageTitle').textContent=im.relative_path||im.name;$('fullImage').src='/naming/image?id='+encodeURIComponent(id);fillViewer(im);if(viewerDrafts[id]){fillViewer(viewerDrafts[id]);viewerDirty=true;dialogError('imageError','已恢复上次未保存的修改，请点“保存本张”。')}openDialog('imageDialog');updateButtons()}
$('fullImage').addEventListener('load',paintRoi);window.addEventListener('resize',paintRoi);
$('imageStage').addEventListener('pointerdown',function(ev){if(busy)return;var p=normalizedPoint(ev,false);if(!p)return;ev.preventDefault();drag={start:p,id:ev.pointerId};this.setPointerCapture(ev.pointerId);roi=[p[0],p[1],0,0];paintRoi()});
$('imageStage').addEventListener('pointermove',function(ev){if(!drag||drag.id!==ev.pointerId)return;var p=normalizedPoint(ev,true);if(!p)return;roi=[Math.min(drag.start[0],p[0]),Math.min(drag.start[1],p[1]),Math.abs(p[0]-drag.start[0]),Math.abs(p[1]-drag.start[1])];paintRoi()});
function endDrag(ev){if(!drag||drag.id!==ev.pointerId)return;drag=null;if(!roi||roi[2]<.005||roi[3]<.005)clearRoi();else paintRoi()}
$('imageStage').addEventListener('pointerup',endDrag);$('imageStage').addEventListener('pointercancel',function(){clearRoi()});
$('clearRoi').addEventListener('click',clearRoi);$('ocrImage').addEventListener('click',function(){if(viewer)startOcr([viewer],roi)});
function viewerModified(){viewerDirty=true;updateButtons()}
$('imageCode').addEventListener('change',function(){$('imageConfirmed').checked=false;viewerModified()});$('imageReplicate').addEventListener('input',function(){$('imageConfirmed').checked=false;viewerModified()});$('imageConfirmed').addEventListener('change',viewerModified);
$('saveImage').addEventListener('click',async function(){if(busy||!viewer)return;var im=imageById(viewer),code=$('imageCode').value,confirmed=$('imageConfirmed').checked;if(confirmed&&!treatment(code)){dialogError('imageError','请先选择有效编号，再确认。');$('imageCode').focus();return}im.code=code;im.replicate=$('imageReplicate').value.trim();im.confirmed=confirmed;setBusy(true);try{await queueAssignment(im,null);delete viewerDrafts[viewer];viewerDirty=false;renderGrid();closeDialog('imageDialog')}catch(err){dialogError('imageError',failText(err))}finally{setBusy(false)}});
$('pickFolder').addEventListener('click',pickFolder);$('openMapping').addEventListener('click',openMapping);$('ocrAll').addEventListener('click',function(){startOcr()});$('confirmVisible').addEventListener('click',confirmVisible);$('previewRename').addEventListener('click',openPreview);
$('search').addEventListener('input',function(){search=this.value.trim().toLowerCase();renderGrid()});$('pendingOnly').addEventListener('change',function(){onlyPending=this.checked;renderGrid()});
loadState().catch(function(err){showMessage('无法连接本地程序：'+failText(err));renderGrid()});
})();
</script>
</body>
</html>'''


